import{_ as d,o,c as r,a0 as e}from"./chunks/framework.Bmhw_dvp.js";const g=JSON.parse('{"title":"推荐方法论 v0.2（大模型独立推导）","description":"","frontmatter":{},"headers":[],"relativePath":"llm_reco/reco-method.md","filePath":"llm_reco/reco-method.md"}'),a={name:"llm_reco/reco-method.md"};function l(n,t,s,i,c,h){return o(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="推荐方法论-v0-2-大模型独立推导" tabindex="-1">推荐方法论 v0.2（大模型独立推导） <a class="header-anchor" href="#推荐方法论-v0-2-大模型独立推导" aria-label="Permalink to &quot;推荐方法论 v0.2（大模型独立推导）&quot;">​</a></h1><blockquote><p>本文件定义&quot;大模型如何判断一个角色强不强&quot;。<strong>本版刻意不参考任何攻略页/官方推荐榜</strong>（讨伐战强度榜、新手指南点名等），只基于角色原始数据与系统机制事实。推理过程见 <code>reasoning-log.md</code>。</p></blockquote><h2 id="_0-先说清楚-什么不算证据" tabindex="-1">0. 先说清楚：什么不算证据 <a class="header-anchor" href="#_0-先说清楚-什么不算证据" aria-label="Permalink to &quot;0. 先说清楚：什么不算证据&quot;">​</a></h2><p>以下来源<strong>不</strong>作为推荐依据（v0.1 的教训）：</p><ul><li>WIKI 的 <code>raid-recommended</code>（官方讨伐战强度榜）&quot;最高评价&quot;标签。</li><li><code>beginner-guide</code>（官方新手指南）&quot;点名核心&quot;。</li><li>任何&quot;XX 是版本答案&quot;的主观评价。 原因：官方榜受版本/当期卡池/主观偏好影响，且会自我循环放大。强不强应由机制本身决定。</li></ul><h2 id="_1-我读取的唯一可信输入" tabindex="-1">1. 我读取的唯一可信输入 <a class="header-anchor" href="#_1-我读取的唯一可信输入" aria-label="Permalink to &quot;1. 我读取的唯一可信输入&quot;">​</a></h2><ol><li><code>char_data.json</code>：370 名角色的 五维 / 必杀技 / 固有效果（中日双语原文）。</li><li>系统机制事实（来自 <code>game-mechanics.md</code>）：伤害公式、intro（移除防御衰减+攻击+200%）、必杀连锁、装备&quot;超昂金&quot;按阵营加成的规则。</li></ol><h2 id="_2-核心定理-从伤害公式推出" tabindex="-1">2. 核心定理（从伤害公式推出） <a class="header-anchor" href="#_2-核心定理-从伤害公式推出" aria-label="Permalink to &quot;2. 核心定理（从伤害公式推出）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>伤害 = 攻击 × 连击倍率 × (1 − DEF/2000)/(1 − MRES/2000)</span></span>
<span class="line"><span>       × (1 + 所有增益%相加) × 必杀倍率</span></span></code></pre></div><ul><li><strong>属性收敛</strong>：满级五维高度集中（攻击/魔法上限 521，体力上限 3200，防御上限 500），绝大多数 SSR 数值相同 → <strong>数值不是区分度，机制才是</strong>。</li><li><strong>增益相加</strong>：多个&quot;不同类&quot;增益比堆高单个增益更划算 → 拥有<strong>稀缺增益类型</strong>的辅助被放大价值。</li><li><strong>防御衰减</strong>：<code>(1 − DEF/2000)</code> 是独立乘区 → &quot;无视防御/贯通&quot;对高防 boss 有非线性收益。</li><li><strong>失败条件</strong>：体力随时间流失，归零即退场 → &quot;不撤退/异常免疫/治疗&quot;直接对抗核心失败条件，权重最高。</li></ul><h2 id="_3-评价维度-按权重" tabindex="-1">3. 评价维度（按权重） <a class="header-anchor" href="#_3-评价维度-按权重" aria-label="Permalink to &quot;3. 评价维度（按权重）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权重</th><th>维度</th><th>判据</th></tr></thead><tbody><tr><td>★★★★★</td><td>机制稀缺度×强度</td><td>全游戏 ≤10 人的机制：不撤退(8)/复活(1)/全异常免疫(1)/攻击增益(3)/魔法增益(1)/破防(14)/减伤(5)/异常解除(19)</td></tr><tr><td>★★★★</td><td>独立乘区叠加</td><td>提供的增益/减益是否属于&quot;稀有类&quot;，能否与队伍其他来源相加</td></tr><tr><td>★★★★</td><td>站场能力</td><td>不撤退 ＞ 异常免疫领域(被动免控) ＞ 持续治疗/减伤</td></tr><tr><td>★★★</td><td>满突成本</td><td>满突★5 的 R ≫ 零突★1 的 SSR（仅用于&quot;新手核心&quot;筛选）</td></tr></tbody></table><h2 id="_4-机制稀缺度速查-全游戏计数" tabindex="-1">4. 机制稀缺度速查（全游戏计数） <a class="header-anchor" href="#_4-机制稀缺度速查-全游戏计数" aria-label="Permalink to &quot;4. 机制稀缺度速查（全游戏计数）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>机制</th><th>人数</th><th>备注</th></tr></thead><tbody><tr><td>不撤退</td><td>8</td><td>极稀有站场；4 个 R/SR</td></tr><tr><td>全异常免疫</td><td>1</td><td>体育祭のヤブルー</td></tr><tr><td>复活</td><td>1</td><td>超昂閃忍ナリカ</td></tr><tr><td>攻击增益</td><td>3</td><td>真夏のイーイー / 魔女ミヤビ / 黒門天・屍寺炎斎</td></tr><tr><td>魔法增益</td><td>1</td><td>魔女ミヤビ（幅度待核）</td></tr><tr><td>破防/贯通</td><td>14</td><td>对高防 boss 非线性收益</td></tr><tr><td>减伤</td><td>5</td><td>FM77 / 閃忍マユリ / ブライドハルカ / 真夏のノドカ / 閃忍ワーグ</td></tr><tr><td>异常解除</td><td>19</td><td>六の法杖セラフィール 等</td></tr><tr><td>异常免疫领域</td><td>约 10+</td><td>制服ニャンコ/閃忍ニャンコ/魔女フタバ(R)/神騎ハニーエル(R) 等</td></tr><tr><td>速度辅助</td><td>126</td><td><strong>通胀技能，不当稀缺</strong></td></tr><tr><td>充能辅助</td><td>105</td><td><strong>通胀技能，不当稀缺</strong></td></tr><tr><td>AoE 全体</td><td>247</td><td><strong>基础能力，非区分度</strong></td></tr></tbody></table><h2 id="_5-应用规则" tabindex="-1">5. 应用规则 <a class="header-anchor" href="#_5-应用规则" aria-label="Permalink to &quot;5. 应用规则&quot;">​</a></h2><ul><li><strong>不按属性榜挑人</strong>：攻击差 21 点对结果影响可忽略。</li><li><strong>不神化速度/充能 R 卡</strong>：它们只对&quot;尚无 SSR 辅助的新手&quot;有价值；满编玩家视为通胀。</li><li><strong>稀缺机制优先</strong>：S 级主体应是&quot;不撤退 / 复活 / 全异常免疫 / 攻击增益 / 破防 / 减伤&quot;持有者。</li><li><strong>免控领域单列</strong>：被动、无消耗的&quot;全队免疫&quot;是性价比最高的对策位。</li><li><strong>诚实标注未核验</strong>：370 人中仅核验约 30 个候选，S 级名单为&quot;经核验的突出样本&quot;，非穷举。</li></ul><blockquote><p>完整推导见 <code>reasoning-log.md</code>；推荐清单见 <code>reco-draft.md</code>。</p></blockquote>`,17)])])}const q=d(a,[["render",l]]);export{g as __pageData,q as default};
